from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], workers: int = 4) -> int:
    """Return the sum of square(x) for every x in xs.

    The squares are computed on a thread pool with `workers` threads.
    The result must be identical for every valid worker count.
    `workers` is keyword-friendly and defaults to 4, so the call
    sum_squares(xs) matches the required signature.
    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return sum(pool.map(square, xs))


def test_matches_serial_sum() -> None:
    xs = list(range(-50, 51))
    assert sum_squares(xs) == sum(square(x) for x in xs)


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 16])
def test_same_result_at_every_worker_count(workers: int) -> None:
    xs = [(i * 7919) % 1000 - 500 for i in range(2000)]
    expected = sum(square(x) for x in xs)
    assert sum_squares(xs, workers=workers) == expected


def test_more_workers_than_items() -> None:
    assert sum_squares([1, 2], workers=8) == 5


def test_empty_list_is_zero() -> None:
    assert sum_squares([]) == 0


def test_single_negative_element() -> None:
    assert sum_squares([-3]) == 9


def test_large_values_are_exact() -> None:
    assert sum_squares([10**12]) == 10**24


def test_order_does_not_change_result() -> None:
    xs = [5, -2, 9, 0, 7, -4]
    assert sum_squares(xs, workers=3) == sum_squares(list(reversed(xs)), workers=3)


def test_rejects_nonpositive_workers() -> None:
    with pytest.raises(ValueError):
        sum_squares([1], workers=0)
